package com.utewedding.app.domain.entity;
import com.utewedding.app.domain.ShopDefaults;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="shipping_provider_operations") public class ShippingProviderOperationEntity{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="shop_id",nullable=false,updatable=false)private UUID shopId=ShopDefaults.PLATFORM_SHOP_ID;@Column(name="shipment_id",nullable=false)private UUID shipmentId;@Column(nullable=false,length=30)private String operation;@Column(name="idempotency_key",nullable=false,unique=true,length=190)private String idempotencyKey;@Column(name="request_hash",nullable=false,length=64)private String requestHash;@Column(nullable=false,length=24)private String status="PENDING";@Column(name="attempt_count",nullable=false)private int attemptCount;@Column(name="provider_reference",length=190)private String providerReference;@JdbcTypeCode(SqlTypes.JSON)@Column(name="sanitized_request",nullable=false,columnDefinition="jsonb")private String sanitizedRequest="{}";@JdbcTypeCode(SqlTypes.JSON)@Column(name="sanitized_response",columnDefinition="jsonb")private String sanitizedResponse;@Column(name="last_error",length=1000)private String lastError;@Column(name="next_attempt_at")private Instant nextAttemptAt;@Column(name="processed_at")private Instant processedAt;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;
 @PrePersist void create(){if(shopId==null)shopId=ShopDefaults.PLATFORM_SHOP_ID;if(createdAt==null)createdAt=Instant.now();if(nextAttemptAt==null)nextAttemptAt=createdAt;} public UUID getId(){return id;}public UUID getShopId(){return shopId;}public void setShopId(UUID v){shopId=v;}public UUID getShipmentId(){return shipmentId;}public void setShipmentId(UUID v){shipmentId=v;}public String getOperation(){return operation;}public void setOperation(String v){operation=v;}public String getIdempotencyKey(){return idempotencyKey;}public void setIdempotencyKey(String v){idempotencyKey=v;}public String getRequestHash(){return requestHash;}public void setRequestHash(String v){requestHash=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public int getAttemptCount(){return attemptCount;}public void setAttemptCount(int v){attemptCount=v;}public String getProviderReference(){return providerReference;}public void setProviderReference(String v){providerReference=v;}public String getSanitizedRequest(){return sanitizedRequest;}public void setSanitizedRequest(String v){sanitizedRequest=v;}public String getSanitizedResponse(){return sanitizedResponse;}public void setSanitizedResponse(String v){sanitizedResponse=v;}public String getLastError(){return lastError;}public void setLastError(String v){lastError=v;}public Instant getNextAttemptAt(){return nextAttemptAt;}public void setNextAttemptAt(Instant v){nextAttemptAt=v;}public Instant getProcessedAt(){return processedAt;}public void setProcessedAt(Instant v){processedAt=v;}public Instant getCreatedAt(){return createdAt;}
}
